#include "png_writer.hpp"
#include <fstream>
#include <vector>
static uint32_t crc(const std::vector<uint8_t>& d){uint32_t c=0xffffffffu;for(uint8_t b:d){c^=b;for(int k=0;k<8;++k)c=(c>>1)^(0xedb88320u&-(c&1));}return c^0xffffffffu;}
static void be(std::vector<uint8_t>& v,uint32_t n){v.push_back(n>>24);v.push_back(n>>16);v.push_back(n>>8);v.push_back(n);}
static void chunk(std::vector<uint8_t>& out,const char* type,const std::vector<uint8_t>& data){std::vector<uint8_t> body(type,type+4);body.insert(body.end(),data.begin(),data.end());be(out,(uint32_t)data.size());out.insert(out.end(),body.begin(),body.end());be(out,crc(body));}
bool writePng(const Image& im,const std::string& path){if(im.width<=0||im.height<=0)return false;std::vector<uint8_t> raw;for(int y=0;y<im.height;++y){raw.push_back(0);for(int x=0;x<im.width;++x){uint8_t p=im.at(x,y);raw.insert(raw.end(),{p,p,p});}}std::vector<uint8_t> z={120,1};size_t pos=0;while(pos<raw.size()){size_t n=std::min<size_t>(65535,raw.size()-pos);bool last=pos+n==raw.size();z.push_back(last?1:0);uint16_t len=(uint16_t)n;z.push_back(len);z.push_back(len>>8);uint16_t inv=~len;z.push_back(inv);z.push_back(inv>>8);z.insert(z.end(),raw.begin()+pos,raw.begin()+pos+n);pos+=n;}uint32_t ad=1,b=0;for(uint8_t x:raw){ad=(ad+x)%65521;b=(b+ad)%65521;}uint32_t sum=(b<<16)|ad;z.insert(z.end(),{(uint8_t)(sum>>24),(uint8_t)(sum>>16),(uint8_t)(sum>>8),(uint8_t)sum});std::vector<uint8_t> out={137,80,78,71,13,10,26,10};std::vector<uint8_t> ihdr;be(ihdr,im.width);be(ihdr,im.height);ihdr.insert(ihdr.end(),{8,2,0,0,0});chunk(out,"IHDR",ihdr);chunk(out,"IDAT",z);chunk(out,"IEND",{});std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size());return f.good();}
